#include "ksStatePostEditTask.h"
#include <iostream>
#include <stdexcept>
using T=ks::StatePostEditTask;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}
int main(){try{uint64_t cases=0;for(bool override:{false,true})for(unsigned field=0;field<65536;++field)for(unsigned enabled:{0u,1u,127u,128u,255u}){const uint32_t base=override?0xffa30000:0x33000;T task(base+field);unsigned reads=0,children=0,clocks=0;auto read=[&](T::Read r)->uint32_t{++reads;return r==T::Read::Override?(override?base:0):r==T::Read::Current?base:enabled;};while(!task.complete()){if(task.awaitingChild()){check(task.child()==(uint8_t(field)==217?T::Child::Rate:T::Child::State),"Post-edit child kind differs");++children;check(task.resumeChild(),"Post-edit child rejected");continue;}const auto c=task.nextClocks(),before=reads;check(!task.advanceBefore(c-1,read)&&before==reads,"Post-edit early read");check(task.advanceBefore(c,read)==c,"Post-edit clocks admission differs");clocks+=c;}
 const unsigned f=uint8_t(field);const bool child=f==217||f==102||f==103||f==84&&enabled;const unsigned expected=override?0:18;const unsigned decision=f==217?29:f==102?35:f==103?41:f==84?(enabled?65:48):30;if(clocks!=expected+103+decision){std::cerr<<"override="<<override<<" field="<<f<<" enabled="<<enabled<<" clocks="<<clocks<<" expected="<<expected+103+decision<<'\n';throw std::runtime_error("Post-edit schedule differs");}check(task.field()==field&&reads==1+unsigned(!override)+unsigned(f==84)&&children==child&&!task.resumeChild(),"Post-edit observations/field wrap differ");++cases;}
 std::cout<<"PASS: "<<cases<<" complete post-edit notifications,all16bit offsets/lowbyte conditions/override+current/enablebytes,typed rate+state children/exact deadlines/clocks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
